import { readdirSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

import { stringify } from "yaml";

import {
  generateOpenApiDocument,
  openApiRegistry,
} from "../src/server/http/openapi";

// Builds docs/openapi.yaml from the Zod schemas the endpoints use (docs/05-API.md,
// section 3). Run from the repository root, like the other scripts.

const ROOT = process.cwd();
const ROUTES_FOLDER = join(ROOT, "src/app/api/v1");
export const OPENAPI_PATH = join(ROOT, "docs/openapi.yaml");

const HEADER =
  "# Generated by `npm run openapi:generate` from the API's Zod schemas. Don't edit by hand.\n";

/** Every route module under /api/v1, in a fixed order. */
function routeModules(): string[] {
  let entries: string[];
  try {
    entries = readdirSync(ROUTES_FOLDER, { recursive: true, encoding: "utf8" });
  } catch {
    return [];
  }
  return entries
    .filter((entry) => /(^|[/\\])route\.ts$/.test(entry))
    .map((entry) => join(ROUTES_FOLDER, entry))
    .sort();
}

/** Imports each route module, which registers its paths, and returns the YAML. */
export async function buildOpenApiYaml(): Promise<string> {
  for (const routeModule of routeModules()) {
    await import(pathToFileURL(routeModule).href);
  }
  const document = generateOpenApiDocument(openApiRegistry);
  return HEADER + stringify(document, { lineWidth: 0 });
}
